// Public document renderer: only client-visible quote data and confirmed work payments.
const LOGO_JPG_B64 = "";
const LOGO_W=260,LOGO_H=260;
const money=n=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS'}).format(n);
const db={settings:{company:'AMC Construcciones y Arreglos',conditions:'',phone:'',validity:15,payment:'A convenir'}};
const quoteTotals=q=>({sale:q.total});
function bytesFromBinary(s) {
  const arr = new Uint8Array(s.length);
  for (let i=0;i<s.length;i++) arr[i] = s.charCodeAt(i) & 255;
  return arr;
}
function cp1252Byte(ch){
  const c = ch.charCodeAt(0);
  if (c <= 255) return c;
  const map = {'€':128,'‚':130,'ƒ':131,'„':132,'…':133,'†':134,'‡':135,'ˆ':136,'‰':137,'Š':138,'‹':139,'Œ':140,'Ž':142,'‘':145,'’':146,'“':147,'”':148,'•':149,'–':150,'—':151,'˜':152,'™':153,'š':154,'›':155,'œ':156,'ž':158,'Ÿ':159};
  return map[ch] || 63;
}
function pdfEsc(s){
  let out = '';
  for (const ch of String(s || '')) {
    const b = cp1252Byte(ch);
    const cc = String.fromCharCode(b);
    if (cc === '\\' || cc === '(' || cc === ')') out += '\\' + cc;
    else if (b === 10 || b === 13) out += ' ';
    else out += cc;
  }
  return out;
}

function makePdf(q){
  const W=595,H=842,L=42,R=553,CW=511,BOTTOM=755;
  const blue='0.035 0.40 0.37',ink='0.12 0.18 0.24',muted='0.38 0.44 0.49',rule='0.82 0.87 0.90';
  const pages=[];let commands=[],y=0;
  const measureCanvas=document.createElement('canvas'),measure=measureCanvas.getContext('2d');
  function width(value,size,bold=false){measure.font=(bold?'bold ':'')+size+'px Arial';return measure.measureText(String(value)).width*1.035;}
  function wrap(value,max,size=11,bold=false){
    const result=[];for(const paragraph of String(value??'').split(/\r?\n/)){
      if(!paragraph.trim()){result.push('');continue;}let line='';
      for(const word of paragraph.trim().split(/\s+/)){
        if(width(word,size,bold)>max){if(line){result.push(line);line='';}let part='';for(const ch of word){if(width(part+ch,size,bold)>max&&part){result.push(part);part='';}part+=ch;}line=part;}
        else if(width(line?line+' '+word:word,size,bold)>max){result.push(line);line=word;}
        else line+=(line?' ':'')+word;
      }if(line)result.push(line);
    }return result.length?result:[''];
  }
  function txt(value,x,top,size=11,bold=false,color=ink){commands.push(`BT ${color} rg /F${bold?2:1} ${size} Tf 1 0 0 1 ${x} ${H-top} Tm (${pdfEsc(value)}) Tj ET`);}
  function box(x,top,w,h,fill,stroke=null){commands.push(`q ${fill} rg ${x} ${H-top-h} ${w} ${h} re f Q`);if(stroke)commands.push(`q ${stroke} RG 0.6 w ${x} ${H-top-h} ${w} ${h} re S Q`);}
  function line(x1,top,x2,color=rule){commands.push(`q ${color} RG 0.6 w ${x1} ${H-top} m ${x2} ${H-top} l S Q`);}
  function newPage(){
    if(commands.length)pages.push(commands);commands=[];
    const company=String(db.settings.company||'AMC CONSTRUCCIONES Y ARREGLOS').toUpperCase();
    const brandLines=wrap(company,414,17,true),brandHeight=brandLines.length*21;
    const headerHeight=Math.max(100,brandHeight+54);
    box(0,0,W,headerHeight,blue);
    const logoSize=62,logoTop=25;commands.push(`q ${logoSize} 0 0 ${logoSize} ${L} ${H-logoTop-logoSize} cm /Im1 Do Q`);
    brandLines.forEach((value,i)=>txt(value,122,43+i*21,17,true,'1 1 1'));
    txt('PRESUPUESTO Y ESTADO DE PAGOS',122,43+brandHeight+9,10,true,'0.76 0.86 0.94');
    const metadataTop=headerHeight+20;
    txt('NÚMERO DE PRESUPUESTO',L,metadataTop,8.5,true,muted);
    const numberLines=wrap(q.number||'Sin número',325,11,true);numberLines.forEach((v,i)=>txt(v,L,metadataTop+19+i*15,11,true));
    txt('FECHA',435,metadataTop,8.5,true,muted);txt(q.date||'',435,metadataTop+19,11);
    y=metadataTop+19+numberLines.length*15+10;line(L,y,R);y+=24;
  }
  function ensure(height){if(y+height>BOTTOM)newPage();}
  function section(title){ensure(58);txt(title,L,y+12,11,true,blue);y+=28;}
  function paragraph(value,size=10.5,color=ink){for(const v of wrap(value,CW,size)){ensure(17);txt(v,L,y+size,size,false,color);y+=17;}}
  function labeled(label,value){const lines=wrap(value||'No informado',CW-26,11);let index=0;while(index<lines.length){ensure(60);const count=Math.max(1,Math.min(lines.length-index,Math.floor((BOTTOM-y-36)/16)));const h=33+count*16;box(L,y,CW,h,'0.96 0.975 0.985',rule);txt(label+(index?' (continuación)':''),L+13,y+17,8.5,true,muted);for(let j=0;j<count;j++)txt(lines[index+j],L+13,y+36+j*16,11);y+=h+10;index+=count;}}
  function tableHeader(){ensure(65);box(L,y,CW,28,'0.90 0.94 0.97');txt('N°',L+12,y+18,9,true,blue);txt('DESCRIPCIÓN DEL TRABAJO',L+49,y+18,9,true,blue);y+=28;}
  newPage();
  labeled('CLIENTE',q.client);
  const town=wrap(q.location||'No informada',305,11),phone=wrap(q.phone||'No informado',153,11),contactHeight=34+Math.max(town.length,phone.length)*16;
  if(contactHeight<200){ensure(contactHeight+14);box(L,y,CW,contactHeight,'0.96 0.975 0.985',rule);txt('LOCALIDAD / DIRECCIÓN',L+13,y+17,8.5,true,muted);txt('TELÉFONO',L+344,y+17,8.5,true,muted);town.forEach((v,i)=>txt(v,L+13,y+36+i*16,11));phone.forEach((v,i)=>txt(v,L+344,y+36+i*16,11));y+=contactHeight+22;}else{labeled('LOCALIDAD / DIRECCIÓN',q.location);labeled('TELÉFONO',q.phone);y+=12;}
  section('TRABAJOS INCLUIDOS');tableHeader();
  const items=q.items||[];
  items.forEach((item,index)=>{
    const lines=wrap(item.clientDescription||'',CW-65,11);let at=0;
    while(at<lines.length){if(BOTTOM-y<44){newPage();section('TRABAJOS INCLUIDOS · CONTINUACIÓN');tableHeader();}
      const count=Math.min(lines.length-at,Math.max(1,Math.floor((BOTTOM-y-24)/16))),height=Math.max(42,count*16+24);
      box(L,y,CW,height,index%2?'0.966 0.976 0.983':'1 1 1');
      txt(at?'...' :String(index+1),L+12,y+24,10,true,muted);
      for(let i=0;i<count;i++)txt(lines[at+i],L+49,y+24+i*16,11);
      line(L,y+height,R);y+=height;at+=count;
    }
  });
  if(!items.length){paragraph('Sin trabajos cargados.');}
  y+=24;ensure(116);
  const totals=quoteTotals(q),totalText=money(totals.sale);let totalSize=26;while(width(totalText,totalSize,true)>CW-36&&totalSize>12)totalSize-=1;
  box(L,y,CW,74,blue);txt('TOTAL FINAL',L+18,y+24,10,true,'0.80 0.88 0.94');txt(totalText,L+18,y+55,totalSize,true,'1 1 1');y+=90;
  ensure(260);section('PAGOS CONFIRMADOS');
  paragraph('Estado actualizado al '+q.snapshotDate+'. Importes en pesos argentinos.',10,muted);y+=12;
  const payments=q.confirmedPayments||[];
  if(!payments.length)paragraph('Todavía no hay pagos confirmados para esta obra.');
  for(const payment of payments){
    ensure(76);box(L,y,CW,28,'0.90 0.94 0.97');txt(payment.date,L+12,y+19,10,true);const value=money(payment.amount);txt(value,R-12-width(value,11,true),y+19,11,true);y+=38;
    paragraph(payment.description||'Pago registrado');y+=14;line(L,y-6,R);
  }
  const paid=Math.round(payments.reduce((n,p)=>n+p.amount,0)*100)/100;
  ensure(93);box(L,y,CW,80,'0.94 0.965 0.98',rule);txt('TOTAL ABONADO',L+16,y+24,10,true,muted);txt(money(paid),L+230,y+24,13,true);txt('SALDO PENDIENTE',L+16,y+57,11,true,blue);txt(money(Math.round((totals.sale-paid)*100)/100),L+230,y+57,19,true,blue);y+=98;
  paragraph('Incluye únicamente pagos registrados o confirmados por AMC. Los comprobantes pendientes no reducen el saldo. Este estado no sustituye una factura ni acredita por sí solo una operación bancaria.',9.5,muted);y+=16;
  section('CONDICIONES DEL PRESUPUESTO');
  paragraph(`Validez: ${q.validity||db.settings.validity} días.    Materiales incluidos: ${q.materialsIncluded||'No'}`);y+=7;
  paragraph(`Forma de pago: ${q.payment||db.settings.payment||'A convenir'}`);y+=7;
  y+=7;
  if(q.notes){section('OBSERVACIONES');paragraph(q.notes);y+=16;}
  if(db.settings.conditions){section('ACLARACIONES');paragraph(db.settings.conditions,10,muted);y+=16;}
  if(db.settings.phone){ensure(40);paragraph('Contacto AMC: '+db.settings.phone,10.5);}
  pages.push(commands);
  const streams=pages.map((cmd,i)=>{commands=cmd;line(L,788,R);txt('AMC · Construcciones y Arreglos',L,805,8.5,false,muted);txt(`Página ${i+1} de ${pages.length}`,470,805,8.5,false,muted);return commands.join('\n');});
  const image=atob(LOGO_JPG_B64),objects=[];objects[1]='<< /Type /Catalog /Pages 2 0 R >>';objects[3]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';objects[4]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>';objects[5]=`<< /Type /XObject /Subtype /Image /Width ${LOGO_W} /Height ${LOGO_H} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${image.length} >>\nstream\n${image}\nendstream`;
  let next=6;const ids=streams.map(()=>({page:next++,content:next++}));objects[2]=`<< /Type /Pages /Kids [${ids.map(x=>x.page+' 0 R').join(' ')}] /Count ${ids.length} >>`;
  streams.forEach((stream,i)=>{objects[ids[i].page]=`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> /XObject << /Im1 5 0 R >> >> /Contents ${ids[i].content} 0 R >>`;objects[ids[i].content]=`<< /Length ${bytesFromBinary(stream).length} >>\nstream\n${stream}\nendstream`;});
  let pdf='%PDF-1.4\n%\xE2\xE3\xCF\xD3\n';const offsets=[0];for(let i=1;i<objects.length;i++){offsets[i]=bytesFromBinary(pdf).length;pdf+=`${i} 0 obj\n${objects[i]}\nendobj\n`;}
  const xref=bytesFromBinary(pdf).length;pdf+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;for(let i=1;i<objects.length;i++)pdf+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';pdf+=`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;return new Blob([bytesFromBinary(pdf)],{type:'application/pdf'});
}




export function paymentDocument(state,workId){
 const w=state.works.find(w=>w.id===workId);if(!w)throw Error('No se encontró la obra.');
 const q=state.quotes.find(q=>q.id===w.quoteId),r=state.requests.find(r=>r.id===q?.requestId);if(!q||!r)throw Error('No se encontró el presupuesto de esta obra.');
 const extras=(state.extras||[]).filter(x=>x.workId===w.id&&x.status==='Aceptado');
 return makePdf({number:q.number,date:q.date.slice(0,10),client:r.name,phone:r.phone,location:w.address||r.town,total:w.budget,validity:q.validity,payment:q.payment,notes:q.notes,materialsIncluded:'Según presupuesto original',snapshotDate:new Date().toLocaleString('es-AR'),items:[...q.items.map(i=>({clientDescription:i.description})),...extras.map(x=>({clientDescription:'ADICIONAL ACEPTADO: '+x.title+' · '+x.description+' · '+money(x.amount)}))],confirmedPayments:w.payments.map(p=>({date:p.date,amount:p.amount,description:p.description}))});
}
export async function downloadPaymentDocument(state,workId){
 const blob=paymentDocument(state,workId),name='AMC-presupuesto-pagos-'+workId.slice(-8)+'.pdf';
 if(window.AndroidBridge?.savePdf){const bytes=new Uint8Array(await blob.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));window.AndroidBridge.savePdf(btoa(binary),name,true);return;}
 const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);
}
